package me.rakkoon69.rakunloots.config;
import me.rakkoon69.rakunloots.items.ItemReference;
import me.rakkoon69.rakunloots.roll.LootChance;
import java.util.*;
public class ProbeLargeChance {
 public static void main(String[] ignored) {
  for(int n:new int[]{500}) {
   List<ContentEntry> entries=new ArrayList<>();
   for(int i=0;i<n;i++) entries.add(new ContentEntry("e"+i,ItemReference.of("","diamond"),1,i<n/2?1:2,OptionalInt.empty()));
   long start=System.nanoTime();
   var chances=LootChance.calculate(new Roll(n/2,n/2,entries));
   double sum=chances.values().stream().mapToDouble(LootChance.EntryChance::probability).sum();
   double budget=n*1e-9;
   System.out.printf(Locale.ROOT,"n=%d total=%.15f expected=%d difference=%.12g maxTotalError=%.12g light=%.15f heavy=%.15f ms=%.1f%n",n,sum,n/2,Math.abs(sum-n/2),budget,chances.get("e0").probability(),chances.get("e"+(n/2)).probability(),(System.nanoTime()-start)/1e6);
   if(!Double.isFinite(sum) || Math.abs(sum-n/2)>budget) throw new AssertionError("At least one marginal error exceeds1e-9");
  }
 }
}
